"""Compute bootstrap confidence intervals for SciERC and DocRED experiments."""

import json
import numpy as np
from pathlib import Path

# --- SciERC normalization (from violation_checker.py) ---

SCIERC_TYPE_MAP = {
    "otherscientificterm": "OtherScientificTerm",
    "other-scientificterm": "OtherScientificTerm",
    "other_scientific_term": "OtherScientificTerm",
    "scientificterm": "OtherScientificTerm",
    "other": "OtherScientificTerm",
}

def scierc_normalize_type(t, valid_types):
    t_lower = t.strip().lower().replace(" ", "").replace("_", "").replace("-", "")
    for vt in valid_types:
        if t_lower == vt.lower().replace(" ", "").replace("_", "").replace("-", ""):
            return vt
    if t_lower in SCIERC_TYPE_MAP:
        return SCIERC_TYPE_MAP[t_lower]
    return None

# --- DocRED normalization (from violation_checker_docred.py) ---

DOCRED_VALID_ENTITY_TYPES = {"PER", "ORG", "LOC", "TIME", "NUM", "MISC"}

DOCRED_ENTITY_TYPE_ALIASES = {
    'PERSON': 'PER', 'PEOPLE': 'PER',
    'ORGANIZATION': 'ORG', 'ORGANISATION': 'ORG',
    'LOCATION': 'LOC',
    'NUMBER': 'NUM', 'NUMERICAL': 'NUM',
    'MISCELLANEOUS': 'MISC',
}

def docred_normalize_entity_type(raw_type):
    t = raw_type.strip().upper()
    return DOCRED_ENTITY_TYPE_ALIASES.get(t, t)

def _levenshtein(s1, s2):
    if len(s1) < len(s2):
        return _levenshtein(s2, s1)
    if len(s2) == 0:
        return len(s1)
    prev_row = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1):
        curr_row = [i + 1]
        for j, c2 in enumerate(s2):
            curr_row.append(min(prev_row[j + 1] + 1, curr_row[j] + 1, prev_row[j] + (c1 != c2)))
        prev_row = curr_row
    return prev_row[-1]

def build_name_to_id(rel_types):
    name_to_id = {}
    for rid, rname in rel_types.items():
        name_to_id[rname.lower().strip()] = rid
        name_to_id[rid.lower()] = rid
    return name_to_id

def docred_normalize_relation(rel_name, rel_types, name_to_id):
    rel_key = name_to_id.get(rel_name.lower().strip())
    if rel_key:
        return rel_key
    rel_tokens = set(rel_name.strip().lower().split())
    best_pid, best_overlap = None, 0.0
    for rid, rname in rel_types.items():
        rname_tokens = set(rname.lower().split())
        if rel_tokens and rname_tokens:
            ratio = len(rel_tokens & rname_tokens) / len(rel_tokens | rname_tokens)
            if ratio > 0.8 and ratio > best_overlap:
                best_overlap = ratio
                best_pid = rid
    if best_pid:
        return best_pid
    for rid, rname in rel_types.items():
        if _levenshtein(rel_name.strip().lower(), rname.lower()) <= 2:
            return rid
    return None

# --- Per-sample stats ---

def scierc_sample_stats(rec, valid_entity_types):
    parsed = rec.get("parsed_output")
    gold_ents = rec.get("gold_entities", [])
    gold_rels = rec.get("gold_relations", [])

    gold_ent_set = set((e["text"].lower().strip(), e["type"]) for e in gold_ents)
    gold_rel_set = set((r["head"].lower().strip(), r["tail"].lower().strip(), r["type"]) for r in gold_rels)

    if parsed is None:
        return {"ent_tp": 0, "ent_gold": len(gold_ent_set), "ent_pred": 0,
                "rel_tp": 0, "rel_gold": len(gold_rel_set), "rel_pred": 0}

    entities = parsed.get("entities", [])
    relations = parsed.get("relations", [])

    pred_ent_set = set()
    for e in entities:
        nt = scierc_normalize_type(e.get("type", ""), valid_entity_types)
        if nt:
            pred_ent_set.add((e.get("text", "").lower().strip(), nt))

    pred_rel_set = set((r.get("head", "").lower().strip(), r.get("tail", "").lower().strip(), r.get("type", "")) for r in relations)

    return {
        "ent_tp": len(gold_ent_set & pred_ent_set), "ent_gold": len(gold_ent_set), "ent_pred": len(pred_ent_set),
        "rel_tp": len(gold_rel_set & pred_rel_set), "rel_gold": len(gold_rel_set), "rel_pred": len(pred_rel_set),
    }

def docred_sample_stats(rec, rel_types, name_to_id):
    parsed = rec.get("parsed_output")
    gold_ents = rec.get("gold_entities", [])
    gold_rels = rec.get("gold_relations", [])

    gold_ent_set = set((e["text"].lower().strip(), docred_normalize_entity_type(e["type"])) for e in gold_ents)
    gold_rel_set = set((r["head"].lower().strip(), r["tail"].lower().strip(), r["type"]) for r in gold_rels)

    if parsed is None:
        return {"ent_tp": 0, "ent_gold": len(gold_ent_set), "ent_pred": 0,
                "rel_tp": 0, "rel_gold": len(gold_rel_set), "rel_pred": 0}

    entities = parsed.get("entities", [])
    relations = parsed.get("relations", [])

    pred_ent_set = set()
    for e in entities:
        nt = docred_normalize_entity_type(e.get("type", ""))
        if nt in DOCRED_VALID_ENTITY_TYPES:
            pred_ent_set.add((e.get("text", "").lower().strip(), nt))

    pred_rel_set = set()
    for r in relations:
        pid = docred_normalize_relation(r.get("type", ""), rel_types, name_to_id)
        if pid:
            pred_rel_set.add((r.get("head", "").lower().strip(), r.get("tail", "").lower().strip(), pid))
        else:
            pred_rel_set.add((r.get("head", "").lower().strip(), r.get("tail", "").lower().strip(), f"__OOV__{r.get('type', '')}"))

    return {
        "ent_tp": len(gold_ent_set & pred_ent_set), "ent_gold": len(gold_ent_set), "ent_pred": len(pred_ent_set),
        "rel_tp": len(gold_rel_set & pred_rel_set), "rel_gold": len(gold_rel_set), "rel_pred": len(pred_rel_set),
    }

# --- Bootstrap ---

def _f1_from_arrays(tp, gold, pred):
    p = np.where(pred > 0, tp / pred, 0.0)
    r = np.where(gold > 0, tp / gold, 0.0)
    denom = p + r
    return np.where(denom > 0, 2 * p * r / denom, 0.0)

def bootstrap_f1(sample_stats, n_bootstrap=10000, seed=42):
    rng = np.random.RandomState(seed)
    n = len(sample_stats)
    tps = np.array([s["tp"] for s in sample_stats])
    golds = np.array([s["gold"] for s in sample_stats])
    preds = np.array([s["pred"] for s in sample_stats])

    indices = rng.randint(0, n, size=(n_bootstrap, n))
    tp_sums = tps[indices].sum(axis=1).astype(float)
    gold_sums = golds[indices].sum(axis=1).astype(float)
    pred_sums = preds[indices].sum(axis=1).astype(float)

    f1_samples = _f1_from_arrays(tp_sums, gold_sums, pred_sums)

    point_p = tps.sum() / preds.sum() if preds.sum() > 0 else 0.0
    point_r = tps.sum() / golds.sum() if golds.sum() > 0 else 0.0
    point_f1 = 2 * point_p * point_r / (point_p + point_r) if (point_p + point_r) > 0 else 0.0

    return {
        "point_estimate": float(point_f1),
        "bootstrap_mean": float(np.mean(f1_samples)),
        "ci_lower": float(np.percentile(f1_samples, 2.5)),
        "ci_upper": float(np.percentile(f1_samples, 97.5)),
        "std": float(np.std(f1_samples)),
    }

def paired_bootstrap_test(stats_a, stats_b, n_bootstrap=10000, seed=42):
    rng = np.random.RandomState(seed)
    n = len(stats_a)
    assert n == len(stats_b)

    tps_a = np.array([s["tp"] for s in stats_a])
    golds_a = np.array([s["gold"] for s in stats_a])
    preds_a = np.array([s["pred"] for s in stats_a])
    tps_b = np.array([s["tp"] for s in stats_b])
    golds_b = np.array([s["gold"] for s in stats_b])
    preds_b = np.array([s["pred"] for s in stats_b])

    indices = rng.randint(0, n, size=(n_bootstrap, n))

    f1_a = _f1_from_arrays(tps_a[indices].sum(axis=1).astype(float),
                           golds_a[indices].sum(axis=1).astype(float),
                           preds_a[indices].sum(axis=1).astype(float))
    f1_b = _f1_from_arrays(tps_b[indices].sum(axis=1).astype(float),
                           golds_b[indices].sum(axis=1).astype(float),
                           preds_b[indices].sum(axis=1).astype(float))

    delta = f1_b - f1_a
    p_value = float(min(2 * min(np.mean(delta <= 0), np.mean(delta >= 0)), 1.0))

    # Point estimates
    pa_p = tps_a.sum() / preds_a.sum() if preds_a.sum() > 0 else 0.0
    pa_r = tps_a.sum() / golds_a.sum() if golds_a.sum() > 0 else 0.0
    f1_a_point = 2 * pa_p * pa_r / (pa_p + pa_r) if (pa_p + pa_r) > 0 else 0.0
    pb_p = tps_b.sum() / preds_b.sum() if preds_b.sum() > 0 else 0.0
    pb_r = tps_b.sum() / golds_b.sum() if golds_b.sum() > 0 else 0.0
    f1_b_point = 2 * pb_p * pb_r / (pb_p + pb_r) if (pb_p + pb_r) > 0 else 0.0

    return {
        "delta_point": float(f1_b_point - f1_a_point),
        "delta_mean": float(np.mean(delta)),
        "ci_lower": float(np.percentile(delta, 2.5)),
        "ci_upper": float(np.percentile(delta, 97.5)),
        "p_value": p_value,
    }

# --- Main ---

def load_jsonl(path):
    records = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                records.append(json.loads(line))
    return records

def extract_stats(sample_stats, metric):
    prefix = "ent" if metric == "entity" else "rel"
    return [{"tp": s[f"{prefix}_tp"], "gold": s[f"{prefix}_gold"], "pred": s[f"{prefix}_pred"]} for s in sample_stats]

def verify_alignment(all_stats, dataset_name):
    configs = list(all_stats.keys())
    ref_ids = [s["doc_id"] for s in all_stats[configs[0]]]
    for cfg in configs[1:]:
        ids = [s["doc_id"] for s in all_stats[cfg]]
        if ids != ref_ids:
            print(f"  WARNING: {dataset_name} {cfg} doc_ids differ from {configs[0]}!")
            return False
    return True

def run_dataset(dataset_name, config_paths, stats_fn, stats_fn_args):
    print(f"\n{'='*50}")
    print(f"  {dataset_name}")
    print(f"{'='*50}")

    all_raw = {}
    all_stats = {}
    for name, path in config_paths.items():
        records = load_jsonl(path)
        raw_with_id = [{"doc_id": r.get("doc_id", i), **stats_fn(r, *stats_fn_args)} for i, r in enumerate(records)]
        all_raw[name] = raw_with_id
        all_stats[name] = [dict((k, v) for k, v in s.items() if k != "doc_id") for s in raw_with_id]

        ent = extract_stats(all_stats[name], "entity")
        rel = extract_stats(all_stats[name], "relation")
        ent_tp, ent_g, ent_p = sum(s["tp"] for s in ent), sum(s["gold"] for s in ent), sum(s["pred"] for s in ent)
        rel_tp, rel_g, rel_p = sum(s["tp"] for s in rel), sum(s["gold"] for s in rel), sum(s["pred"] for s in rel)
        ent_f1 = 2*ent_tp/(ent_g+ent_p) if (ent_g+ent_p) > 0 else 0
        rel_f1 = 2*rel_tp/(rel_g+rel_p) if (rel_g+rel_p) > 0 else 0
        print(f"  {name}: {len(records)} samples, Ent F1={100*ent_f1:.2f}%, Rel F1={100*rel_f1:.2f}%")

    verify_alignment(all_raw, dataset_name)

    per_config = {}
    for name, stats in all_stats.items():
        ent_ci = bootstrap_f1(extract_stats(stats, "entity"))
        rel_ci = bootstrap_f1(extract_stats(stats, "relation"))
        per_config[name] = {"ent_f1": ent_ci, "rel_f1": rel_ci}
        print(f"  {name} CI: Ent F1={100*ent_ci['point_estimate']:.2f}% [{100*ent_ci['ci_lower']:.2f}, {100*ent_ci['ci_upper']:.2f}], "
              f"Rel F1={100*rel_ci['point_estimate']:.2f}% [{100*rel_ci['ci_lower']:.2f}, {100*rel_ci['ci_upper']:.2f}]")

    comparisons = {}
    pairs = [
        ("unconstrained", "grammar_only"),
        ("unconstrained", "semantic_only"),
        ("unconstrained", "full_s1"),
        ("grammar_only", "full_s1"),
        ("semantic_only", "full_s1"),
    ]
    print(f"\n  Paired bootstrap tests (B - A):")
    for cfg_a, cfg_b in pairs:
        if cfg_a not in all_stats or cfg_b not in all_stats:
            continue
        ent_test = paired_bootstrap_test(extract_stats(all_stats[cfg_a], "entity"),
                                          extract_stats(all_stats[cfg_b], "entity"))
        rel_test = paired_bootstrap_test(extract_stats(all_stats[cfg_a], "relation"),
                                          extract_stats(all_stats[cfg_b], "relation"))
        key = f"{cfg_a}_vs_{cfg_b}"
        comparisons[key] = {"ent_f1_delta": ent_test, "rel_f1_delta": rel_test}
        print(f"  {key}:")
        print(f"    Ent ΔF1={100*ent_test['delta_point']:+.2f}pp [{100*ent_test['ci_lower']:+.2f}, {100*ent_test['ci_upper']:+.2f}] p={ent_test['p_value']:.4f}")
        print(f"    Rel ΔF1={100*rel_test['delta_point']:+.2f}pp [{100*rel_test['ci_lower']:+.2f}, {100*rel_test['ci_upper']:+.2f}] p={rel_test['p_value']:.4f}")

    return {"per_config": per_config, "comparisons": comparisons}


if __name__ == "__main__":
    import os
    os.chdir("/root/schema_semantic_constrained_ie")

    # SciERC
    with open("ontology_constraints.json") as f:
        scierc_constraints = json.load(f)
    scierc_valid_types = scierc_constraints["entity_types"]

    scierc_configs = {
        "unconstrained": "outputs/phase2_scierc_unconstrained.jsonl",
        "grammar_only": "outputs/phase2_scierc_grammar_only.jsonl",
        "semantic_only": "outputs/phase2_scierc_semantic_only_v2.jsonl",
        "full_s1": "outputs/phase2_scierc_full_s1_v2.jsonl",
    }
    scierc_results = run_dataset("SciERC", scierc_configs, scierc_sample_stats, (scierc_valid_types,))

    # DocRED
    with open("data/docred/ontology_constraints_docred.json") as f:
        docred_constraints = json.load(f)
    docred_rel_types = docred_constraints.get("relation_types", {})
    docred_name_to_id = build_name_to_id(docred_rel_types)

    docred_configs = {
        "unconstrained": "outputs/docred_unconstrained.jsonl",
        "grammar_only": "outputs/docred_grammar_only.jsonl",
        "semantic_only": "outputs/docred_semantic_only.jsonl",
        "full_s1": "outputs/docred_full_s1.jsonl",
    }
    docred_results = run_dataset("DocRED", docred_configs, docred_sample_stats, (docred_rel_types, docred_name_to_id))

    # Save results
    def round_recursive(obj, decimals=6):
        if isinstance(obj, float):
            return round(obj, decimals)
        if isinstance(obj, dict):
            return {k: round_recursive(v, decimals) for k, v in obj.items()}
        if isinstance(obj, list):
            return [round_recursive(v, decimals) for v in obj]
        return obj

    results = {
        "scierc": round_recursive(scierc_results),
        "docred": round_recursive(docred_results),
